export function paymentDues(s,actor,now=Date.now()){return Object.values(s.bookings).filter(b=>b.personId===actor&&b.status==='confirmed'&&b.paymentStatus==='unpaid'&&b.priceCents>0&&s.matches[b.matchId]?.status==='active'&&Date.parse(s.matches[b.matchId].startsAt)>now).sort((a,b)=>Date.parse(s.matches[a.matchId].startsAt)-Date.parse(s.matches[b.matchId].startsAt));}
export const VERSION_FEATURES={v001:['release001a','release001b','release001c'],v002:['release002a','release002b','release002c','release002d','release002e','release002f'],v003:['release003a','release003b'],v005:['release005a','release005b','release005c'],v004:['release004a','release004b','release004c','release004d','release004e']};
export function comparedVersions(from,to){const order=['v000','v001','v002','v003','v004','v005'],a=order.indexOf(from),b=order.indexOf(to);return order.slice(Math.min(a,b)+1,Math.max(a,b)+1).map(version=>({version,features:VERSION_FEATURES[version]||[]}));}
